    private static String normalizeFile(String text) {return text.replaceAll("called in .*? on line (\\d+)","called in @FILE@ on line $1");}
    private static void check(String name,String source,String expected)throws Throwable {
        var failures=new ArrayList<String>();
        for(boolean debug:new boolean[]{false,true})for(boolean phb:new boolean[]{false,true}) {
            var out=new ByteArrayOutputStream();var scope=new CompileScope();scope.setPhpLanguageProfile(PhpLanguageProfile.PHP_8_5);scope.setDebugMode(debug);
            scope.registerExtension(new php.runtime.ext.CoreExtension());scope.registerExtension(new php.runtime.ext.SPLExtension());
            scope.registerExtension(new org.develnext.jphp.zend.ext.standard.StandardExtension());
            var env=new Environment(scope,out);
            try {
                var context=new Context("<?php\n"+source,new File(name+".php"));context.setPhpLanguageProfile(PhpLanguageProfile.PHP_8_5);
                var module=new JvmCompiler(env,context).compile(false);
                if(phb){var bytes=new ByteArrayOutputStream();var codec=new ModuleDumper(context,env,debug);codec.save(module,bytes);module=codec.load(new ByteArrayInputStream(bytes.toByteArray()));}
                scope.setPhpLanguageProfile(PhpLanguageProfile.JPHP_LEGACY);
                scope.loadModule(module);scope.addUserModule(module);env.registerModule(module);module.include(env);env.flushAll();
                assertEquals(name,normalizeFile(expected),normalizeFile(out.toString(StandardCharsets.UTF_8)));
            }catch(Throwable failure){failures.add(name+"/debug="+debug+"/phb="+phb+": "+failure);}
            finally{env.doFinal();}
        }
        assertTrue(String.join("\n",failures),failures.isEmpty());
    }
